function validate([words]) {
  if (words.length < 1 || words.length > 1000) return 'words needs 1 to 1000 strings.';
  const size = words[0].length;
  if (size < 1 || size > 4) return 'Each word has 1 to 4 letters.';
  if (words.some(word => word.length !== size)) return 'All words must have the same length.';
  if (words.some(word => !/^[a-z]+$/.test(word))) return 'Words use only lowercase English letters.';
  if (new Set(words).size !== words.length) return 'The words must be distinct.';
  return null;
}

