function wordSquares(words) {
  const size = words[0].length;
  const byPrefix = new Map();
  for (const word of words) {
    for (let len = 0; len < size; len++) {
      const prefix = word.slice(0, len);
      if (!byPrefix.has(prefix)) byPrefix.set(prefix, []);
      byPrefix.get(prefix).push(word);
    }
  }
  const result = [];
  const square = [];
  function build() {
    if (square.length === size) {
      result.push([...square]);
      return;
    }
    const row = square.length;
    let prefix = '';
    for (const word of square) {
      prefix += word[row];
    }
    const candidates = byPrefix.get(prefix) || [];
    for (const word of candidates) {
      square.push(word);
      build();
      square.pop();
    }
  }
  build();
  return result;
}

