function wordSquares(words) {
  const size = words[0].length;
  const found = [];
  const rows = [];
  // The top-left block of the rows chosen so far must read the same across and down.
  const symmetric = () => {
    for (let i = 0; i < rows.length; i++)
      for (let j = 0; j < i; j++)
        if (rows[i][j] !== rows[j][i]) return false;
    return true;
  };
  const extend = () => {
    if (rows.length === size) { found.push(rows.slice()); return; }
    for (const word of words) {
      rows.push(word);
      if (symmetric()) extend();
      rows.pop();
    }
  };
  extend();
  return found;
}

