function generate(rand, size) {
  const pick = (letters, length) => Array.from({ length }, () => letters[Math.floor(rand() * letters.length)]).join('');
  if (size === 'large') {
    const seen = new Set();
    while (seen.size < 1000) seen.add(pick('abcdefghijklmnopqrstuvwxyz', 4));
    return [[...seen]];
  }
  const length = 1 + Math.floor(rand() * 4);
  const letters = 'abc'.slice(0, 1 + Math.floor(rand() * 3));
  const count = 1 + Math.floor(rand() * Math.min(letters.length ** length, 8));
  const seen = new Set();
  while (seen.size < count) seen.add(pick(letters, length));
  return [[...seen]];
}
